solution.solution.cpp:
#include <cstdint>
#include <vector>

inline std::uint64_t mix(std::uint64_t x)
{
    x ^= x >> 30; x *= 0xbf58476d1ce4e5b9ULL;
    x ^= x >> 27; x *= 0x94d049bb133111ebULL;
    x ^= x >> 31;
    return x;
}

class ProbeSet
{
public:
    ProbeSet() : keys_(8), state_(8, Empty) {}

    bool insert(std::uint64_t key)
    {
        if (contains(key)) return false;
        if ((size_ + tombstones_ + 1) * 4 > capacity() * 3)
            rebuild((size_ + 1) * 2 > capacity() ? capacity() * 2 : capacity());
        std::size_t i = home(key);
        while (state_[i] == Full) i = (i + 1) & (capacity() - 1);
        if (state_[i] == Tombstone) --tombstones_;
        keys_[i] = key;
        state_[i] = Full;
        ++size_;
        return true;
    }

    bool contains(std::uint64_t key) const { return locate(key) != npos; }

    bool erase(std::uint64_t key)
    {
        std::size_t i = locate(key);
        if (i == npos) return false;
        state_[i] = Tombstone;
        --size_;
        ++tombstones_;
        return true;
    }

    std::size_t size() const { return size_; }
    std::size_t capacity() const { return keys_.size(); }
    std::size_t tombstones() const { return tombstones_; }

private:
    enum State : unsigned char { Empty, Full, Tombstone };
    static constexpr std::size_t npos = static_cast<std::size_t>(-1);

    std::size_t home(std::uint64_t key) const { return static_cast<std::size_t>(mix(key)) & (capacity() - 1); }

    std::size_t locate(std::uint64_t key) const
    {
        for (std::size_t i = home(key), steps = 0; steps < capacity(); i = (i + 1) & (capacity() - 1), ++steps)
        {
            if (state_[i] == Empty) return npos;
            if (state_[i] == Full && keys_[i] == key) return i;
        }
        return npos;
    }

    void rebuild(std::size_t newCapacity)
    {
        std::vector<std::uint64_t> oldKeys = std::move(keys_);
        std::vector<State> oldState = std::move(state_);
        keys_.assign(newCapacity, 0);
        state_.assign(newCapacity, Empty);
        size_ = 0;
        tombstones_ = 0;
        for (std::size_t j = 0; j < oldKeys.size(); ++j)
        {
            if (oldState[j] != Full) continue;
            std::size_t i = home(oldKeys[j]);
            while (state_[i] == Full) i = (i + 1) & (capacity() - 1);
            keys_[i] = oldKeys[j];
            state_[i] = Full;
            ++size_;
        }
    }

    std::vector<std::uint64_t> keys_;
    std::vector<State> state_;
    std::size_t size_ = 0;
    std::size_t tombstones_ = 0;
};

unitTests:
#include <unordered_set>

TEST("insert and contains") {
    ProbeSet s;
    CHECK(s.insert(42));
    CHECK(!s.insert(42));
    CHECK(s.contains(42));
    CHECK(!s.contains(7));
    CHECK_EQ(s.size(), std::size_t{ 1 });
    CHECK_EQ(s.capacity(), std::size_t{ 8 });
}
TEST("growing") {
    ProbeSet s;
    for (std::uint64_t k = 1; k <= 6; ++k) s.insert(k * 1000);
    CHECK_EQ(s.capacity(), std::size_t{ 8 });              // 6 of 8 slots is exactly 3/4
    s.insert(7000);
    CHECK_EQ(s.capacity(), std::size_t{ 16 });
    for (std::uint64_t k = 8; k <= 1000; ++k) s.insert(k * 1000);
    CHECK_EQ(s.size(), std::size_t{ 1000 });
    CHECK_EQ(s.capacity(), std::size_t{ 2048 });
    bool all = true;
    for (std::uint64_t k = 1; k <= 1000; ++k) all = all && s.contains(k * 1000);
    CHECK(all);
    CHECK(!s.contains(999));
}
TEST("erasing leaves tombstones that searches skip") {
    ProbeSet s;
    for (std::uint64_t k = 0; k < 6; ++k) s.insert(k);
    CHECK_EQ(s.capacity(), std::size_t{ 8 });
    for (std::uint64_t k = 0; k < 6; k += 2) CHECK(s.erase(k));
    CHECK(!s.erase(0));
    CHECK_EQ(s.size(), std::size_t{ 3 });
    CHECK_EQ(s.tombstones(), std::size_t{ 3 });
    for (std::uint64_t k = 1; k < 6; k += 2) CHECK(s.contains(k));
    for (std::uint64_t k = 0; k < 6; k += 2) CHECK(!s.contains(k));
    CHECK(s.insert(2));                                    // 3 keys + 3 tombstones + 1 > 6: rebuilt at the same size
    CHECK(s.contains(2));
    CHECK_EQ(s.size(), std::size_t{ 4 });
    CHECK_EQ(s.tombstones(), std::size_t{ 0 });
    CHECK_EQ(s.capacity(), std::size_t{ 8 });
}
TEST("tombstones are cleared by a rebuild") {
    ProbeSet s;
    for (int round = 0; round < 100000; ++round)
    {
        s.insert(round);
        s.erase(round);
    }
    CHECK_EQ(s.size(), std::size_t{ 0 });
    CHECK_EQ(s.capacity(), std::size_t{ 8 });
    CHECK(s.tombstones() <= 6);
}
TEST("matches std::unordered_set") {
    ProbeSet s;
    std::unordered_set<std::uint64_t> ref;
    std::uint64_t x = 88172645463325252ULL;
    bool same = true;
    for (int step = 0; step < 50000; ++step)
    {
        x ^= x << 13; x ^= x >> 7; x ^= x << 17;
        std::uint64_t key = x % 3000;
        if (x & 1) same = same && (s.insert(key) == ref.insert(key).second);
        else same = same && (s.erase(key) == (ref.erase(key) == 1));
    }
    CHECK(same);
    CHECK_EQ(s.size(), ref.size());
    CHECK((s.size() + s.tombstones()) * 4 <= s.capacity() * 3);
}

